function overview(){return `<div class="page-head"><div><div class="eyebrow">MARKETING ANALYTICS / CASE 01</div><h1>让每一笔广告预算，都有依据。</h1><p>以 Air France 搜索广告案例，完成一场需要独立核算、修正判断和方案答辩的经营调查。</p></div><div class="head-meta">120 MIN<br>产品 · 运营 · 数据分析</div></div><div class="grid-main"><div><section class="case-intro"><div class="case-tag">KELLOGG CASE · KEL319 / KEL321</div><h2>Air France<span class="red-stroke"></span></h2><p>作为 Media Contacts 的分析团队，你需要比较搜索广告渠道与活动的经营表现，为 Air France 提出下一轮投放建议。</p><div class="meta-line"><span>搜索引擎广告 SEM</span><span>渠道 → 活动 → 关键词</span><span>Excel / 数据透视表</span></div></section><div class="section-head"><h2>你的四个决策</h2><span>10 分钟导入 + 100 分钟调查 + 10 分钟讲评</span></div><div class="lesson-grid">${lessons.map(l=>`<a class="lesson" href="#${l.id}"><div class="lesson-top"><span class="lesson-number">${l.n}</span><span class="lesson-time">${l.time} 分钟</span></div><div class="lesson-tag">${l.tag}</div><h3>${l.title}</h3><p>${l.desc}</p><div class="lesson-bottom"><span>${l.output}</span><b>↗</b></div></a>`).join('')}</div><section class="panel" style="margin-top:24px"><h3>一条完整的经营决策线</h3><div class="flow"><div class="flow-step"><strong>定义目标</strong><span>用什么衡量成功</span></div><div class="flow-step"><strong>评估渠道</strong><span>把钱投向哪里</span></div><div class="flow-step"><strong>诊断投放</strong><span>具体调整什么</span></div><div class="flow-step"><strong>制定方案</strong><span>怎么验证与复盘</span></div></div></section></div><aside class="side-stack"><section class="panel aside-card"><h3>开始前，准备好数据</h3><span class="pill">官方配套表格待导入</span><p style="margin-top:15px">使用 KEL321 配套 Excel。导入后，课程中的图表会依据你的文件计算。</p><a class="button primary" href="#data">准备案例数据 ↗</a><div class="stat-line"><span>课程时长</span><strong>120 分钟</strong></div><div class="stat-line"><span>系列大题</span><strong>4 道</strong></div><div class="stat-line"><span>算法要求</span><strong>无需建模</strong></div></section><section class="panel aside-card"><h3>案例从哪里来</h3><p>Kellogg 正式教学案例，NYU Stern 数字营销分析课程采用。</p><a class="source-link" href="${sources.case}" target="_blank" rel="noopener">Kellogg 官方案例 ↗<small>业务背景与学习目标</small></a><a class="source-link" href="${sources.nyu}" target="_blank" rel="noopener">NYU 课程大纲 ↗<small>Digital Marketing Analytics</small></a><a class="source-link" href="#brief">阅读案例简报 →</a></section></aside></div>`}
export {overview};
